import clsx from 'clsx';
import * as CSS from 'csstype';
import React, {
  type ElementType,
  type MouseEventHandler,
  type PointerEvent,
  type ReactElement,
  type ReactNode,
  forwardRef,
  useMemo,
} from 'react';
import { useIntl } from 'react-intl';
import { isElement } from 'react-is';

import { buttonCSS, buttonLoadingCSS, buttonWidthsCSS } from './Button.sty.js';
import { Label } from './Label.js';
import { Prefix } from './Prefix.js';
import { Suffix } from './Suffix.js';
import { ProgressCircle } from '../../core/components/progress/ProgressCircle.js';
import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { _useSharedInputPropsContext } from '../../core/hooks/useSharedInputPropsContext.js';
import { useFocusRing } from '../../core/styles/useFocusRing.js';
import type {
  AriaLabelingProps,
  AriaDisabledProps,
} from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Grid } from '../../layouts-core/grid/Grid.js';
import { fieldColorsCSS } from '../../styles/field.sty.js';

//#region Typings

/**
 * TextAlign options
 * @deprecated Will be removed
 */
export type TextAlignOptionsType = 'center' | 'start';

/**
 * Width options
 * @deprecated Will be removed
 */
export type ButtonWidthOptionsType = 'content' | 'full';

/**
 * Size options
 * @deprecated Will be removed
 */
export type ButtonSizeOptionsType = 'default' | 'condensed';

/**
 * HTML Button Type
 * @deprecated Will be removed
 */
export const behaviorTypeOptions = ['button', 'submit', 'reset'] as const;
/** @deprecated Will be removed */
export type ButtonBehaviorType = (typeof behaviorTypeOptions)[number];

export interface ButtonOwnProps
  extends AriaLabelingProps,
    AriaDisabledProps,
    WithChildren,
    StylingProps,
    DataTestId {
  /**
   * If a button is disabled e.g. it cannot be interacted with.
   * @defaultValue false
   */
  disabled?: boolean;

  /**
   * Different variants have different styles.
   * @defaultValue 'default'
   */
  variant?: 'default' | 'emphasized' | 'accent';

  /**
   * The HTML button type.
   * @see https://developer.mozilla.org/en-US/docs/Web/HTML/Element/button#attr-type
   * @defaultValue 'button'
   */
  type?: 'button' | 'reset' | 'submit';

  /** Called when the button is interacted with. */
  onClick?: MouseEventHandler;

  /**
   * The width of the button.
   * @defaultValue 'content'
   */
  // eslint-disable-next-line @typescript-eslint/ban-types
  width?: 'content' | 'full' | CSS.Property.Width<string & {}>;

  /**
   * The color of the button. This should be chosen based on the context
   * the button is used in.
   * @defaultValue 'neutral'
   */
  color?: 'primary' | 'neutral' | 'success' | 'critical' | 'warning';

  /**
   * Controls the text alignment inside the button. Only affects the button
   * if the width is not set to 'content'.
   * @defaultValue 'center'
   */
  textAlign?: 'center' | 'start';

  /**
   * The size of the button.
   * @defaultValue 'default'
   */
  size?: 'default' | 'condensed';

  /**
   * The current loading state of the button. If true, a loading icon is shown and the button is disabled.
   * @defaultValue false
   */
  loading?: boolean;
}

// Merge own props with others inherited from the underlying element type
export type ButtonProps<E extends ElementType> = PolymorphicComponentProps<
  E,
  ButtonOwnProps
>;

type ButtonSlots = {
  label?: ReactNode;
  prefix?: ReactNode;
  suffix?: ReactNode;
  freeform?: ReactNode[];
};

//#endregion

/** Iterates over child nodes to extract specific component slots. */
function getButtonSlots(children: ReactNode) {
  const slots: ButtonSlots = {};

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case Suffix:
          slots.suffix = child;
          break;
        case Prefix:
          slots.prefix = child;
          break;
        case Label:
          slots.label = child;
          break;
        default:
          slots.freeform ??= [];
          slots.freeform.push(child);
          break;
      }
    } else {
      if (child) {
        slots.freeform ??= [];
        slots.freeform.push(child);
      }
    }
  });

  return slots;
}

export const _Button: <E extends ElementType = 'button'>(
  props: ButtonProps<E>,
) => ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends ElementType>(props: ButtonProps<E>, ref: typeof props.ref) => {
    const {
      children,
      variant = 'default',
      disabled: propDisabled = false,
      'aria-disabled': ariaDisabledProp,
      required: propRequired = false,
      id: propId,
      type = 'button',
      onClick,
      ariaLabel,
      width = 'content',
      color = 'neutral',
      textAlign = 'center',
      size = 'default',
      loading = false,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      as,
      ...remainingProps
    }: ButtonProps<E> = props;
    const slots = getButtonSlots(children);

    const { required, disabled, id, labelId } = _useSharedInputPropsContext({
      required: propRequired,
      disabled: propDisabled,
      id: propId,
    });

    const ariaDisabled =
      ariaDisabledProp === true || ariaDisabledProp === 'true';
    const nativeDisabledOrLoading = useMemo(
      () => (loading ? true : disabled),
      [disabled, loading],
    );
    const disabledOrLoading = useMemo(
      () => nativeDisabledOrLoading || ariaDisabled,
      [ariaDisabled, nativeDisabledOrLoading],
    );

    const { focusProps, focusClassName } = useFocusRing({
      variant: !disabledOrLoading ? color : 'neutral',
      disabled: nativeDisabledOrLoading,
    });

    const ariaLabelingProps = _useAriaLabelingProps(remainingProps);

    const handleButtonClick: MouseEventHandler<HTMLElement> = (event) => {
      if (disabledOrLoading) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }

      onClick?.(event);
    };

    const buttonProps = {
      ref,
      'data-testid': dataTestId,
      required,
      disabled: nativeDisabledOrLoading && !ariaDisabled,
      id,
      type,
      ...ariaLabelingProps,
      'aria-labelledby': labelId
        ? labelId === id
          ? id
          : `${labelId} ${id}`
        : undefined,
      'aria-disabled': ariaDisabledProp,
      onClick: handleButtonClick,
    };

    // Propagation needs to be disabled on the disabled button because
    // it would still trigger actions on parents that would listen to it.
    // For example the menu or the useOverlay hook.
    const disabledPropagationProps = {
      onPointerDown(evt: PointerEvent) {
        if (nativeDisabledOrLoading) {
          evt.preventDefault();
          evt.stopPropagation();
        }
      },
      onPointerUp(evt: PointerEvent) {
        if (nativeDisabledOrLoading) {
          evt.preventDefault();
          evt.stopPropagation();
        }
      },
    };

    const hasChildren = children || children === 0;

    const buttonMergedProps = {
      ..._mergeProps(
        buttonProps,
        disabledPropagationProps,
        // Need to cast this one as the inference of mergeProps would generate
        // a not allowed overlap. The remainingProps type is too complex due to the
        // polymorphic inheritance.
        remainingProps as Record<string, unknown>,
        focusProps,
      ),
    };

    const intl = useIntl();

    // Make the component polymorphic
    const Component = as || 'button';

    // Render a void element if no children are set and it's not loading (so self-closing polymorphed tags won't break)
    if (!hasChildren) {
      return (
        <Component
          {...buttonMergedProps}
          className={clsx(
            consumerClassName,
            fieldColorsCSS({ variant, color, disabled: disabledOrLoading }),
            buttonCSS({
              disabled: disabledOrLoading,
              textAlign,
              size,
            }),
            buttonWidthsCSS[width],
            focusClassName,
          )}
          style={{
            width: width !== 'content' && width !== 'full' ? width : undefined,
          }}
        />
      );
    }

    return (
      <Component
        className={clsx(
          consumerClassName,
          fieldColorsCSS({ variant, color, disabled: disabledOrLoading }),
          buttonCSS({
            disabled: disabledOrLoading,
            textAlign,
            size,
          }),
          buttonWidthsCSS[width],
          focusClassName,
        )}
        style={{
          width: width !== 'content' && width !== 'full' ? width : undefined,
          ...consumerStyle,
        }}
        {...buttonMergedProps}
      >
        {loading && (
          <div className={buttonLoadingCSS}>
            <ProgressCircle
              size="small"
              variant={color}
              aria-label={intl.formatMessage({
                defaultMessage: 'Loading',
                id: 'cycz+bYG+VH7Of4e',
                description: 'Label for the loading state.',
              })}
            />
          </div>
        )}
        <Grid
          gap={4}
          grid="auto / auto-flow auto"
          width={'100%'}
          maxWidth="100%"
          alignItems="center"
          justifyContent={textAlign === 'start' ? 'space-between' : 'center'}
          style={{
            visibility: loading ? 'hidden' : undefined,
          }}
        >
          {textAlign === 'start' ? (
            <Flex minWidth={0} gap={4}>
              {slots.prefix}
              {slots.label}
              {slots.freeform && <Button.Label>{slots.freeform}</Button.Label>}
            </Flex>
          ) : (
            <>
              {slots.prefix}
              {slots.label}
              {slots.freeform && <Button.Label>{slots.freeform}</Button.Label>}
            </>
          )}
          {slots.suffix}
        </Grid>
      </Component>
    );
  },
);

(_Button as typeof _Button & { displayName: string }).displayName = 'Button';

/**
 * Buttons allow users to trigger actions or events
 * with a single click anywhere within the button container.
 * Users can also trigger a button by pressing
 * `Enter` or `Space` while the button has focus.
 */
export const Button = Object.assign(_Button, {
  Suffix,
  Prefix,
  Label,
});
